from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
import json,hashlib
R=Path(__file__).resolve().parent
views=['front','rear','side','three-quarter','face','abdomen','clay','gameplay','abdomen-oblique','abdomen-clay','footwear']
checks={};records=[]
for view in views:
 a=Image.open(R/'renders'/f'before-{view}.png').convert('RGB');b=Image.open(R/'renders'/f'after-{view}.png').convert('RGB');checks[view]=a.size==b.size
 records.append({'view':view,'dimensions':a.size,'before_sha256':hashlib.sha256((R/'renders'/f'before-{view}.png').read_bytes()).hexdigest(),'after_sha256':hashlib.sha256((R/'renders'/f'after-{view}.png').read_bytes()).hexdigest()})
 if view in ['front','face','abdomen','abdomen-clay','footwear']:
  width=720;h=round(a.height*width/a.width);sheet=Image.new('RGB',(width*2,h+54),(20,22,29));d=ImageDraw.Draw(sheet);d.text((18,18),'ORIGINAL CANDIDATE A',fill='white');d.text((width+18,18),'FINAL ATTEMPT — VISUAL GATE FAILED',fill=(255,177,130));sheet.paste(a.resize((width,h)),(0,54));sheet.paste(b.resize((width,h)),(width,54));sheet.save(R/'renders'/f'compare-{view}.jpg',quality=94)
